/// <summary>
/// PricingAttribute of table <c>WHSProductVariantFixedLocation</c> field WMSLocationId.
/// </summary>
/// [GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Product, GUPPricingAttributeSourceLevel::Line)]
internal class GUPPricingAttributeWHSProductVariantFixedLocationWMSLocationId extends GUPPricingAttributeWHSProductVariantFixedLocation implements GUPIPricingAttribute
{
}

Method.Source:
    public Set getAllowedValues()
    {
        var                            ret = new Set(Types::String);
        WHSProductVariantFixedLocation wHSProductVariantFixedLocation;

        while select wHSProductVariantFixedLocation
            group by WMSLocationId
        {
            if (! ret.in(wHSProductVariantFixedLocation.WMSLocationId))
            {
                ret.add(wHSProductVariantFixedLocation.WMSLocationId);
            }
        }

        return ret;
    }

    protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
    {
        QueryBuildRange qbr;

        qbr = _qbds.addRange(fieldNum(WHSProductVariantFixedLocation, WMSLocationId));
        qbr.value(queryValue(_value));
    }
